denials.command:
mkdir -p /tmp/ra-introspect/log
seq 2000 | awk '
  {
    if ($1 == 42 || $1 == 137 || $1 == 250 || $1 == 500 || $1 == 750 || $1 == 1500 || $1 == 1999) {
      print $1 " ERROR something failed at step " $1
    } else {
      print $1 " INFO normal operation at step " $1
    }
  }
' > /tmp/ra-introspect/log/app.log
echo "=== byte size ==="
wc -c < /tmp/ra-introspect/log/app.log
echo "=== line count ==="
wc -l < /tmp/ra-introspect/log/app.log
echo "=== ERROR line count ==="
grep -c "ERROR" /tmp/ra-introspect/log/app.log
echo "=== ERROR lines (number:content) ==="
grep -n "ERROR" /tmp/ra-introspect/log/app.log

